typedef uint64_t obj_t;

/* immediates (see smarv.html SS3) */
#define SCM_FALSE ((obj_t)0)
#define SCM_TRUE  ((obj_t)1)
#define SCM_NULL  ((obj_t)13)          /* imm itag 3 << 2 | 01 */
#define SCM_VOID  ((obj_t)21)
#define SCM_UNIT  ((obj_t)25)
#define SCM_EOF   ((obj_t)29)

/* block headers: hdr = (size<<3) | (mtag<<1) | 1 */
#define SCM_HDR(size, mtag) \
  ((((obj_t)(size)) << 3) | (((obj_t)(mtag)) << 1) | (obj_t)1)
#define MTAG_TYPED   0                 /* cell 0 is rtd (#f: values tuple) */
#define MTAG_PACKED  1                 /* box (size 1), pair (size 2) */
#define MTAG_CLOSURE 2                 /* cell 0 is code ptr -- not scanned */
#define MTAG_VECTOR  3
#define SCM_BOX_HDR  SCM_HDR(1, MTAG_PACKED)   /* 0x0b */
#define SCM_PAIR_HDR SCM_HDR(2, MTAG_PACKED)   /* 0x13 */

/* native (foreign) object types, as in Skint's n.h */
typedef struct cxtype_s {
  const char *tname;
  void (*free)(void *);
} cxtype_t;

/* (free handlers are installed by init: WCPL does not accept
   function pointers in static initializers) */
static cxtype_t string_cxtype     = { "string", NULL };
static cxtype_t bytevector_cxtype = { "bytevector", NULL };
static cxtype_t port_cxtype       = { "port", NULL };
static cxtype_t hvector_cxtype    = { "hvector", NULL };

/* exported GC globals (see scmrt.mvh) */
void    *heap_limit;                   /* base of the active semispace */
int64_t  heap_plus1;                   /* region base + 1 word, as i64 */
int64_t  hmask;                        /* in-heap test mask */

/* heap state */
static unsigned char *rt_region;       /* region base (8-byte aligned) */
static unsigned char *rt_region_raw;   /* malloc block holding region */
static size_t         rt_region_bytes; /* total region size, pow2 */
static unsigned char *rt_static_lo;
static unsigned char *rt_static_bump;
static unsigned char *rt_static_hi;
static unsigned char *rt_semi[2];
static size_t         rt_semi_bytes;
static int            rt_active;
static int            rt_ready;
static size_t         rt_roots_init;   /* from init's reg_words */

/* ------------------------------------------------------------------ */
/* small helpers                                                       */

/* The static area holds literals and global-store boxes.  That is a
   property of the PROGRAM and does not grow with the heap, so it gets a
   fixed size rather than the two-semispaces' worth it used to get.
   Measured across the benchmark corpus, actual use is 2 KB to 83 KB
   (nucleic is the heaviest at 82,952 bytes); 2 MiB is both ~25x that
   and exactly the capacity a program got at startup before, so nothing
   that starts today can run out sooner.
   Sizing it as 2S was expensive wherever address space is finite,
   because the region is static + two semispaces and the usable
   semispace is what is left over: earley ended a run with 8 GiB of
   static capacity holding 2,272 bytes.  On wasm32 the allocator cannot
   serve a block above 1 GiB at all (its top bucket is 2^31 and sbrk
   takes a SIGNED 32-bit increment, so a 2 GiB request arrives as
   INT32_MIN and trips an assert, which compiles to `unreachable'), and
   under the old layout that 1 GiB bought only a 256 MiB semispace.
   With this it buys ~511 MiB, which is the whole point. [cco] */
/* RIGHT-SIZED FROM THE MODULE, not a constant.  init's $static_words
   is what the compiler counted: the blocks its own literals will
   deserialize into, plus room for the runtime's own few.  A constant
   cannot be right in either direction -- too small aborts a
   literal-heavy program with "static area exhausted", too large
   reserves address space that on wasm32 comes straight out of the
   heap -- and the compiler is the only party that knows the answer.
   The floor is for init(0,0,0), which is only the ensure_init path. */
#define RT_STATIC_FLOOR ((size_t)64 * 1024)

static size_t rt_static_bytes = RT_STATIC_FLOOR;

static size_t rt_static_for(int32_t static_words)
{
  size_t b;
  if (static_words <= 0) return RT_STATIC_FLOOR;
  b = (size_t)static_words * sizeof(obj_t);
  /* whole pages, so the semispaces start page-aligned */
  b = (b + 4095u) & ~(size_t)4095u;
  return b < RT_STATIC_FLOOR ? RT_STATIC_FLOOR : b;
}

/* the region is one power-of-two block so that hmask stays a single
   base-plus-mask test: big enough for the static area and both
   semispaces, and no bigger */
static size_t rt_region_for(size_t semi_bytes)
{
  size_t need = rt_static_bytes + 2 * semi_bytes, r = 4096;
  while (r < need) {
    if (r > (size_t)-1 / 2) {
      fprintf(stderr, "scmrt: heap region too large\n");
      exit(1);
    }
    r <<= 1;
  }
  return r;
}

/* and the semispace is whatever is left of it, after the static area */
static size_t rt_semi_for(size_t region_bytes)
{
  size_t s = (region_bytes - rt_static_bytes) / 2;
  return s & ~(size_t)7;              /* whole words */
}

static obj_t mk_fixnum(int64_t v)
{
  return (obj_t)(((uint64_t)v & 0x3fffffffULL) << 2) | (obj_t)3;
}

/* flonum <-> obj bit conversion; under WCPL the intrinsics from
   <sys/intrs.h> (pulled in by <math.h>) compile to single
   i64.reinterpret_f64 / f64.reinterpret_i64 instructions.
   (WCPL only accepts conditional directives at file scope, hence
   the split here rather than inside the function bodies.) */
#if defined(__WCPL__)
static obj_t mk_flonum(double d)
{
  return ~__builtin_asuint64(d);
}

static double flo_val(obj_t o)
{
  return __builtin_asdouble(~o);
}
#else
static obj_t mk_flonum(double d)
{
  union { double d; uint64_t u; } cvt;
  cvt.d = d;
  return ~cvt.u;
}

static double flo_val(obj_t o)
{
  union { double d; uint64_t u; } cvt;
  cvt.u = ~o;
  return cvt.d;
}
#endif

static int is_objptr(obj_t o)
{
  if (!rt_region) return 0;
  return ((o - (obj_t)(uint64_t)heap_plus1) & (obj_t)(uint64_t)hmask) == 0;
}

/* Skint's is_flonum (n.h, NAN_BOXING): a flonum is the bitwise
   complement of a double, and for every finite double the high
   16 bits of that complement are nonzero.  Immediates live in
   the low 32 bits and heap pointers have zero high bits, so
   this is disjoint from fixnums and every other class -- there
   is no bit-pattern overlap to alias. */
static int is_flonum(obj_t o)
{
  return (o & (obj_t)0xffff000000000000ULL) != 0;
}

static int is_fixnum(obj_t o)
{
  return (o & (obj_t)0xffffffff00000003ULL) == 3;   /* isim0 */
}

static char *dup_bytes(const char *s, size_t n)
{
  char *p = (char *)malloc(n + 1);
  if (!p) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  memcpy(p, s, n);
  p[n] = '\0';
  return p;
}

/* allocate a block in the immortal static area; returns its cells */
static obj_t *static_block(obj_t hdr, size_t ncells)
{
  obj_t *w = (obj_t *)(void *)rt_static_bump;
  if (rt_static_bump + (ncells + 1) * sizeof(obj_t) > rt_static_hi) {
    fprintf(stderr, "scmrt: static area exhausted\n");
    abort();
  }
  rt_static_bump += (ncells + 1) * sizeof(obj_t);
  /* cleared as it is handed out: the region is not bulk-zeroed, and
     the collector scans [static_lo, static_bump) as roots, so no
     cell may reach it uninitialized [cco] */
  memset(w, 0, (ncells + 1) * sizeof(obj_t));
  w[0] = hdr;
  return w + 1;
}

static obj_t native_obj(cxtype_t *t, void *payload)
{
  obj_t *cell = static_block((obj_t)(uintptr_t)t, 1);
  cell[0] = (obj_t)(uintptr_t)payload;
  return (obj_t)(uintptr_t)cell;
}

/* ------------------------------------------------------------------ */
/* startup                                                             */

void *init(int32_t init_heap_words, int32_t reg_words,
           int32_t static_words)
{
  size_t semi_words = 256;
  if (rt_ready)
    return rt_semi[rt_active] + rt_semi_bytes;
  if (init_heap_words > 0)
    while (semi_words < (size_t)init_heap_words) semi_words <<= 1;
  rt_static_bytes = rt_static_for(static_words);
  rt_semi_bytes   = semi_words * sizeof(obj_t);
  rt_region_bytes = rt_region_for(rt_semi_bytes);
  rt_semi_bytes   = rt_semi_for(rt_region_bytes);
  {
    /* The region needs no power-of-two alignment.  Every in-region
       test -- the compiler's inlined notobjptr, ct_is_objptr,
       ct_ptr_in -- subtracts the region base first, so hmask has
       only to bound the offset; the one alignment hmask does demand
       is 8 bytes, because its bit 0 rejects odd offsets, and malloc
       provides 16.  Over-allocating in order to align spent a second
       region's worth of address space, and it was that factor, not
       the live set, that earley ran out of: a 4 GB semispace asks for
       a 16 GB region, which this host grants, where the same heap
       asked for 32 GB before, which it does not.  The region is not
       bulk-zeroed either: the collector reads the static area only up
       to rt_static_bump and a semispace only down to $hp, and a grown
       region's static tail has never been zeroed, so nothing depended
       on it.  static_block clears what it hands out. [cco] */
    unsigned char *raw = (unsigned char *)malloc(rt_region_bytes);
    if (!raw) { fprintf(stderr, "scmrt: cannot allocate heap\n"); abort(); }
    rt_region = raw;
    rt_region_raw = raw;
  }
  rt_static_lo   = rt_region;
  rt_static_bump = rt_region;
  rt_static_hi   = rt_region + rt_static_bytes;
  rt_semi[0]     = rt_region + rt_static_bytes;
  rt_semi[1]     = rt_region + rt_static_bytes + rt_semi_bytes;
  rt_active      = 0;
  heap_limit     = rt_semi[0];
  heap_plus1     = (int64_t)(uintptr_t)(rt_region + sizeof(obj_t));
  hmask          = (int64_t)(0xffff000000000001ULL
                             | ~(uint64_t)(rt_region_bytes - 1));
  rt_roots_init  = reg_words > 0 ? (size_t)reg_words : 64;
  string_cxtype.free     = &free;
  bytevector_cxtype.free = &free;
  hvector_cxtype.free    = &free;
  rt_ready       = 1;
  return rt_semi[0] + rt_semi_bytes;   /* initial $hp: semispace top */
}

static void ensure_init(void)
{
  if (!rt_ready) (void)init(0, 0, 0);
}

/* ------------------------------------------------------------------ */
/* registered roots                                                    */

static obj_t **rt_roots;
static size_t  rt_roots_len, rt_roots_cap;

void *register_root(void *slot_addr)
{
  ensure_init();
  if (rt_roots_len == rt_roots_cap) {
    rt_roots_cap = rt_roots_cap ? rt_roots_cap * 2 : rt_roots_init;
    rt_roots = (obj_t **)realloc(rt_roots,
                                 rt_roots_cap * sizeof(obj_t *));
    if (!rt_roots) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  }
  rt_roots[rt_roots_len++] = (obj_t *)slot_addr;
  return slot_addr;
}

obj_t deserialize_sexp(void *cstr, void *r, void *hp);

/* register n consecutive 8-byte cells starting at base (a whole
   $gstore segment) as GC roots */
void register_roots_range(void *base, int32_t n)
{
  int32_t i;
  for (i = 0; i < n; i++)
    register_root((char *)base + i * 8);
}

/* materialize n literal globals: tab holds n (cell_offset,
   blob_offset) i32 pairs; each literal is deserialized from
   lits+blob_offset and stored into gstore+cell_offset */
void *deserialize_all(void *lits, void *tab, int32_t n,
                      void *gstore, void *r, void *hp)
{
  int32_t i;
  /* tab is authored little-endian by definition (same byte-array
     serialization as the literal blob), so assemble each i32 from
     its 4 bytes explicitly: reading it through a native int32_t*
     would scramble the (cell, blob) pairs on big-endian hosts */
  const unsigned char *t = (const unsigned char *)tab;
  for (i = 0; i < n; i++) {
    const unsigned char *e = t + 8 * i;
    int32_t cell_off = (int32_t)((uint32_t)e[0] | ((uint32_t)e[1] << 8)
                                 | ((uint32_t)e[2] << 16) | ((uint32_t)e[3] << 24));
    int32_t blob_off = (int32_t)((uint32_t)e[4] | ((uint32_t)e[5] << 8)
                                 | ((uint32_t)e[6] << 16) | ((uint32_t)e[7] << 24));
    obj_t o = deserialize_sexp((char *)lits + blob_off, r, hp);
    *(obj_t *)(void *)((char *)gstore + cell_off) = o;
  }
  return hp;
}

/* ------------------------------------------------------------------ */
/* Cheney copying collector                                            */

static unsigned char *rt_to_bump;      /* next copy goes below this */

/* state of the collection pass in progress (normal or growing) */
static unsigned char *ct_from_base;    /* from-space being evacuated */
static size_t         ct_from_bytes;
static unsigned char *ct_to_base;      /* to-space receiving copies */
static size_t         ct_to_bytes;
static unsigned char *ct_static_from;  /* static area of the old region */
static size_t         ct_static_bytes; /* its size (2 * old semispace) */
static unsigned char *ct_static_to;    /* static area of the new region */
static int64_t        ct_old_plus1;    /* old region's mask-test base */
static int64_t        ct_old_hmask;    /* old region's mask */
static int            ct_growing;      /* relocating to a larger region */

/* global-store boxes live in the static area; defined further below */
static void rebase_global_store(obj_t old_base, size_t old_bytes,
                                obj_t new_base);

/* obj_t values the runtime itself caches in C statics (the standard
   ports, the command line, the values tag) also point into the
   static area; defined further below */
static void rebase_runtime_caches(obj_t old_base, size_t old_bytes,
                                  obj_t new_base);

static int ct_is_objptr(obj_t o)
{
  return ((o - (obj_t)(uint64_t)ct_old_plus1)
          & (obj_t)(uint64_t)ct_old_hmask) == 0;
}

static int ct_ptr_in(obj_t o, unsigned char *base, size_t bytes)
{
  return (o - (obj_t)(uintptr_t)base) < (obj_t)bytes;
}

/* Skint terminates the process when a grown heap cannot be allocated */
static void grow_out_of_memory(size_t semi_words)
{
  fprintf(stderr,
          "scmrt: out of memory: cannot grow heap to %zu words\n",
          semi_words);
  exit(1);
}

static long rt_gc_count, rt_gc_grows;
static unsigned long long rt_gc_forwarded;

/* forward (tentative) declarations for the verify debug code;
   the definitions live in the symbols section below */
static char **rt_syms;
static size_t rt_syms_len, rt_syms_cap;

static obj_t forward(obj_t o)
{
  obj_t *cell, *dst;
  obj_t h;
  size_t words;
  if (!ct_is_objptr(o)) return o;
  /* static-area objects never move (on growth they are rebased to
     the same offset in the new region's static area) */
  if (ct_ptr_in(o, ct_static_from, ct_static_bytes))
    return ct_growing
      ? (obj_t)((uintptr_t)o
                + (uintptr_t)(ct_static_to - ct_static_from))
      : o;
  /* already in to-space (this also defuses forwarding words met as
     cell values) */
  if (o - (obj_t)(uintptr_t)ct_to_base
      < (obj_t)ct_to_bytes + sizeof(obj_t))
    return o & ~(obj_t)3;
  /* only the from-space is evacuated; anything else in the region
     (the inactive semispace, padding) is left untouched */
  if (!ct_ptr_in(o, ct_from_base, ct_from_bytes)) return o;
  cell = (obj_t *)(uintptr_t)o;
  h = cell[-1];
  if ((h & 3) == 2) return h & ~(obj_t)3;      /* forwarding pointer */
  words = (h & 1) ? (size_t)(h >> 3) + 1 : 2;  /* native: 2 words */
  if (words * sizeof(obj_t) > ct_from_bytes + ct_to_bytes) {
    fprintf(stderr,
            "scmrt: corrupt heap object at %p: header 0x%llx words=%llu\n",
            (void *)(uintptr_t)o, (unsigned long long)h,
            (unsigned long long)words);
    abort();
  }
  rt_gc_forwarded += words;
  rt_to_bump -= words * sizeof(obj_t);
  dst = (obj_t *)(void *)rt_to_bump;
  memcpy(dst, cell - 1, words * sizeof(obj_t));
  cell[-1] = (obj_t)(uintptr_t)(dst + 1) | (obj_t)2;
  return (obj_t)(uintptr_t)(dst + 1);
}

typedef struct natrec_s {
  obj_t    *hdr_slot;                  /* header word in from-space */
  cxtype_t *type;
  void     *payload;
} natrec_t;

static natrec_t *rt_nats;
static size_t    rt_nats_len, rt_nats_cap;

static void natrec_push(obj_t *slot, cxtype_t *t, void *payload)
{
  if (rt_nats_len == rt_nats_cap) {
    rt_nats_cap = rt_nats_cap ? rt_nats_cap * 2 : 256;
    rt_nats = (natrec_t *)realloc(rt_nats, rt_nats_cap * sizeof(natrec_t));
    if (!rt_nats) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  }
  rt_nats[rt_nats_len].hdr_slot = slot;
  rt_nats[rt_nats_len].type = t;
  rt_nats[rt_nats_len].payload = payload;
  rt_nats_len++;
}

/* One Cheney pass: evacuate from_base into to_base, updating the
   roots (the caller's regs[0..live-1], the registered slots, and the
   static area).  When growing is set, the static area has already
   been copied to static_to in the new region: its words still hold
   old-region pointers and are updated there, static pointers are
   rebased, and registered slots living in the static area move too.
   Returns the new allocation pointer (bump pointer of to-space). */
static void *collect_pass(obj_t *regs, int32_t live, void *hp,
                          unsigned char *from_base, size_t from_bytes,
                          unsigned char *to_base, size_t to_bytes,
                          unsigned char *static_to, int growing)
{
  unsigned char *p, *top;
  int32_t i;
  size_t k;
  ct_from_base    = from_base;
  ct_from_bytes   = from_bytes;
  ct_to_base      = to_base;
  ct_to_bytes     = to_bytes;
  ct_static_from  = rt_static_lo;
  ct_static_bytes = rt_static_bytes;
  ct_static_to    = static_to;
  ct_old_plus1    = heap_plus1;
  ct_old_hmask    = hmask;
  ct_growing      = growing;

  /* record from-space natives so the dead ones can be finalized
     once forwarding has decided who survived */
  rt_nats_len = 0;
  top = from_base + from_bytes;
  for (p = (unsigned char *)hp; p < top;) {
    obj_t h = *(obj_t *)(void *)p;
    if ((h & 3) == 0)
      natrec_push((obj_t *)(void *)p, (cxtype_t *)(uintptr_t)h,
                  (void *)(uintptr_t)*(obj_t *)(void *)(p + sizeof(obj_t)));
    p += ((h & 1) ? ((size_t)(h >> 3) + 1) : 2) * sizeof(obj_t);
  }

  rt_to_bump   = to_base + to_bytes;

  /* roots: the caller's live range, registered slots, static area */
  if (regs)
    for (i = 0; i < live; i++) {
      regs[i] = forward(regs[i]);
    }
  for (k = 0; k < rt_roots_len; k++) {
    obj_t *slot = rt_roots[k];
    if (growing
        && (unsigned char *)slot >= ct_static_from
        && (unsigned char *)slot < ct_static_from + ct_static_bytes)
      rt_roots[k] = slot =
        (obj_t *)(void *)(static_to + ((unsigned char *)slot
                                       - ct_static_from));
    *slot = forward(*slot);
  }
  {
    unsigned char *sbase = growing ? static_to : rt_static_lo;
    size_t sused = (size_t)(rt_static_bump - rt_static_lo);
    for (p = sbase; p < sbase + sused; p += sizeof(obj_t)) {
      *(obj_t *)(void *)p = forward(*(obj_t *)(void *)p);
    }
  }

  /* Cheney scan, as Skint's relocate (k.c) does it: a reverse word
     scan over to-space down to the allocation frontier, which forward
     keeps pushing lower, and no worklist.  The explicit queue this
     replaces held one pointer per copied object, which on earley
     meant some 2.7 GB of side table beside a 1.1 GB live set, grown
     by doubling realloc on the hot path.  Word granularity is sound
     because the object encoding is Skint's: every non-pointer a cell
     can hold is rejected by the same mask the inlined notobjptr test
     uses -- block headers, fixnums, chars, '() and #t have bit 0 set,
     #f is 0 so its offset underflows, a flonum has nonzero high 16
     bits, and a closure's code pointer, a native's cxtype_t header
     and a native's malloc'd payload all lie outside the region.  So
     scanning a header or a code pointer is a no-op rather than a case
     to skip, and to-space itself never holds a forwarding word, since
     forward writes those into from-space. [cco] */
  {
    obj_t *q = (obj_t *)(void *)(to_base + to_bytes);
    while ((unsigned char *)q > rt_to_bump) {
      q -= 1;
      *q = forward(*q);
    }
  }

  /* finalize natives that were not forwarded */
  for (k = 0; k < rt_nats_len; k++)
    if ((*rt_nats[k].hdr_slot & 3) != 2 && rt_nats[k].type->free != NULL)
      (*rt_nats[k].type->free)(rt_nats[k].payload);

  return rt_to_bump;
}

/* GC diagnostics, enabled with SCMRT_GC_STATS=1 in the environment:
   collection/growth counts and words copied are reported on stderr
   at exit.  Used to compare GC behaviour against Skint's cxm_hgc. */
static double rt_gc_time;

/* Seconds on a monotonic clock, or 0 where there is no such clock.
   WCPL's time.h has neither struct timespec nor clock_gettime, so the
   whole platform dependency lives here rather than at each of the
   three timing sites in collect: nesting one test around one function
   is what WCPL's preprocessor subset allows, and it keeps the callers
   free of conditionals.  The gc-time figure in the SCMRT_GC_STATS
   report is simply 0 on the wasm target. [cco] */
#ifndef __WCPL__
static double rt_monotonic(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (double)ts.tv_sec + 1e-9 * (double)ts.tv_nsec;
}
#else
static double rt_monotonic(void)
{
  return 0.0;
}
#endif
static void rt_gc_stats_report(void)
{
  /* static-bytes is here because the static area is sized as a multiple
     of the semispace while what it actually holds -- literals and global
     boxes -- is a property of the PROGRAM and does not grow with the
     heap.  On a 32-bit target that overcommitment is expensive: the
     region is static + two semispaces, and the usable semispace is
     whatever is left. [cco] */
  fprintf(stderr,
          "scmrt-gc: collects=%ld grows=%ld forwarded-words=%llu "
          "semi-words=%llu static-bytes=%llu/%llu gc-time=%.3f\n",
          rt_gc_count, rt_gc_grows, rt_gc_forwarded,
          (unsigned long long)(rt_semi_bytes / sizeof(obj_t)),
          (unsigned long long)(size_t)(rt_static_bump - rt_static_lo),
          (unsigned long long)(size_t)(rt_static_hi - rt_static_lo),
          rt_gc_time);
}
/* file scope, not function scope: WCPL does not accept a block-level
   static, and this runtime is compiled by it for the wasm target.  The
   wasm build had never been attempted on this file, so the violation
   sat here from its first commit. [cco] */
static int rt_gc_stats_armed;

static void rt_gc_stats_arm(void)
{
  const char *e;
  if (rt_gc_stats_armed) return;
  rt_gc_stats_armed = 1;
  e = getenv("SCMRT_GC_STATS");
  /* &f, not f: WCPL does not apply the function-to-pointer decay in
     argument position, which is why init installs its free handlers as
     &free too [cco] */
  if (e && e[0] == '1') atexit(&rt_gc_stats_report);
}

void *collect(void *r, int32_t live, void *hp, int32_t needs)
{
  double gc_t0;
  obj_t *regs = (obj_t *)(void *)r;
  rt_gc_stats_arm();
  rt_gc_count++;
  gc_t0 = rt_monotonic();
  if (getenv("SCMRT_GC_STATS") && rt_gc_count <= 20)
    fprintf(stderr,
            "scmrt-gc: collect #%ld live=%d needs=%d used-words=%lld\n",
            rt_gc_count, (int)live, (int)needs,
            (unsigned long long)((rt_semi[rt_active] + rt_semi_bytes
                                  - (unsigned char *)hp)
                                 / sizeof(obj_t)));
  unsigned char *new_hp, *old_raw, *new_region, *new_raw;
  size_t semi_words, live_words, want, new_semi_words;
  size_t new_semi_bytes, new_region_bytes, used_static;
  ensure_init();

  /* first pass: collect into the other semispace as usual */
  new_hp = (unsigned char *)collect_pass(
      regs, live, hp, rt_semi[rt_active], rt_semi_bytes,
      rt_semi[rt_active ^ 1], rt_semi_bytes, rt_static_lo, 0);
  rt_active  ^= 1;
  heap_limit  = rt_semi[rt_active];

  /* Skint's bump policy (cxm_hgc): the request is charged, in
     addition, twice the live size, so the heap is left at most half
     full; if that does not fit, the semispaces are doubled (below)
     until it does, instead of aborting */
  semi_words = rt_semi_bytes / sizeof(obj_t);
  live_words = (size_t)(rt_semi[rt_active] + rt_semi_bytes - new_hp)
               / sizeof(obj_t);
  want = needs > 0 ? (size_t)needs : 0;
  if (want > (size_t)-1 - 2 * live_words) grow_out_of_memory(want);
  want += 2 * live_words;
  if (semi_words >= want) {
    rt_gc_time += rt_monotonic() - gc_t0;
    return new_hp;
  }

  rt_gc_grows++;
  /* grow: double the semispace size until the request fits */
  new_semi_words = semi_words;
  while (new_semi_words < want) {
    if (new_semi_words > (size_t)-1 / 2) grow_out_of_memory(want);
    new_semi_words *= 2;
  }
  if (new_semi_words > (size_t)-1 / (4 * sizeof(obj_t)))
    grow_out_of_memory(new_semi_words);
  new_semi_bytes   = new_semi_words * sizeof(obj_t);
  new_region_bytes = rt_region_for(new_semi_bytes);
  new_semi_bytes   = rt_semi_for(new_region_bytes);
  new_raw = (unsigned char *)malloc(new_region_bytes);
  if (!new_raw) grow_out_of_memory(new_semi_words);
  new_region = new_raw;

  /* copy the static area across (same offsets), then relocate the
     live objects from the current semispace into semispace 0 of the
     new region; the pass rebases static pointers and updates the
     static area, the registered slots, and rt_roots as it goes */
  used_static = (size_t)(rt_static_bump - rt_static_lo);
  memcpy(new_region, rt_static_lo, used_static);
  if (regs
      && (unsigned char *)regs >= rt_static_lo
      && (unsigned char *)regs < rt_static_lo + rt_static_bytes)
    regs = (obj_t *)(void *)(new_region
                             + ((unsigned char *)regs - rt_static_lo));
  old_raw = rt_region_raw;
  new_hp = (unsigned char *)collect_pass(
      regs, live, new_hp, rt_semi[rt_active], rt_semi_bytes,
      new_region + rt_static_bytes, new_semi_bytes, new_region, 1);
  rebase_global_store((obj_t)(uintptr_t)rt_region, rt_static_bytes,
                      (obj_t)(uintptr_t)new_region);
  rebase_runtime_caches((obj_t)(uintptr_t)rt_region, rt_static_bytes,
                        (obj_t)(uintptr_t)new_region);

  /* adopt the new region (static 2S + semispaces at 2S and 3S) */
  rt_region       = new_region;
  rt_region_raw   = new_raw;
  rt_region_bytes = new_region_bytes;
  rt_semi_bytes   = new_semi_bytes;
  rt_static_lo    = new_region;
  rt_static_bump  = new_region + used_static;
  rt_static_hi    = new_region + rt_static_bytes;
  rt_semi[0]      = new_region + rt_static_bytes;
  rt_semi[1]      = new_region + rt_static_bytes + new_semi_bytes;
  rt_active       = 0;
  heap_limit      = rt_semi[0];
  heap_plus1      = (int64_t)(uintptr_t)(rt_region + sizeof(obj_t));
  hmask           = (int64_t)(0xffff000000000001ULL
                               | ~(uint64_t)(rt_region_bytes - 1));
  free(old_raw);
  rt_gc_time += rt_monotonic() - gc_t0;
  return new_hp;
}

/* ------------------------------------------------------------------ */
/* symbols and the global store                                        */

/* rt_syms, rt_syms_len and rt_syms_cap are defined once, up with the
   collector that reads them: C merges a tentative definition with a
   later one, but WCPL rejects the pair as "symbol already defined",
   and this file is compiled by it for the wasm target. [cco] */

static obj_t intern_bytes(const char *s, size_t n)
{
  size_t i;
  for (i = 0; i < rt_syms_len; i++)
    if (strlen(rt_syms[i]) == n && memcmp(rt_syms[i], s, n) == 0)
      return ((obj_t)i << 8) | (obj_t)17;       /* SYMBOL itag 4 */
  if (rt_syms_len >= ((size_t)1 << 24)) {
    fprintf(stderr, "scmrt: too many symbols\n");
    abort();
  }
  if (rt_syms_len == rt_syms_cap) {
    rt_syms_cap = rt_syms_cap ? rt_syms_cap * 2 : 256;
    rt_syms = (char **)realloc(rt_syms, rt_syms_cap * sizeof(char *));
    if (!rt_syms) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  }
  rt_syms[rt_syms_len] = dup_bytes(s, n);
  return ((obj_t)(rt_syms_len++) << 8) | (obj_t)17;
}

obj_t intern_sym(void *cstr)
{
  const char *s = (const char *)cstr;
  return intern_bytes(s, strlen(s));
}

typedef struct gnode_s {
  char           *name;
  obj_t           box;
  struct gnode_s *next;
} gnode_t;

static gnode_t *rt_gstore[991];

static unsigned rt_hash(const char *s)
{
  unsigned h = 5381;
  int c;
  while ((c = (unsigned char)*s++) != 0) h = h * 33u + (unsigned)c;
  return h % 991u;
}

obj_t global_loc(void *cstr, void *hp)
{
  const char *name = (const char *)cstr;
  gnode_t *g;
  unsigned b;
  (void)hp;                       /* boxes live in the static area */
  ensure_init();
  b = rt_hash(name);
  for (g = rt_gstore[b]; g; g = g->next)
    if (strcmp(g->name, name) == 0) return g->box;
  g = (gnode_t *)malloc(sizeof(gnode_t));
  if (!g) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  g->name = dup_bytes(name, strlen(name));
  {
    obj_t *cell = static_block(SCM_BOX_HDR, 1);
    cell[0] = SCM_VOID;
    g->box = (obj_t)(uintptr_t)cell;
  }
  g->next = rt_gstore[b];
  rt_gstore[b] = g;
  return g->box;
}

/* heap growth: global-store boxes live in the static area, so their
   recorded obj values must be rebased when the region moves */
static void rebase_global_store(obj_t old_base, size_t old_bytes,
                                obj_t new_base)
{
  unsigned b;
  gnode_t *g;
  for (b = 0; b < 991u; b++)
    for (g = rt_gstore[b]; g; g = g->next)
      if (g->box - old_base < (obj_t)old_bytes)
        g->box += new_base - old_base;
}

/* ------------------------------------------------------------------ */
/* Skint-format literal deserialization (rds_sexp)                     */
/* Format: a one-letter code followed by payload, no whitespace:     */
/*   f t n    #f #t ()          c<char>        character (%XX, %uXXXX, */
/*   i<int>   fixnum            j<real>        flonum   %UXXXXXXXX)    */
/*   p a b    pair              l<n>: e...     proper list             */
/*   v<n>: e...  vector         s<n>: chars    string                  */
/*   y<n>: chars   symbol       b<n>: bytes    bytevector (hex bytes)  */
/*   h<n>:<t>: e...  homogeneous vector (';' separated elements)       */
/*   z e      box                                                     */

typedef struct rds_s { const char *p; } rds_t;

static int rds_getc(rds_t *s)
{
  return *s->p ? (unsigned char)*s->p++ : -1;
}

static int hexval(int c)
{
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return 0;
}

static int rds_char_tok(rds_t *s)
{
  int c = rds_getc(s);
  int c1, c2, v, i;
  if (c != '%') return c;
  c1 = rds_getc(s);
  c2 = rds_getc(s);
  if (c1 == 'u' || c1 == 'U') {
    int ndig = (c1 == 'u') ? 4 : 8;
    v = hexval(c2);
    for (i = 1; i < ndig; i++) v = v * 16 + hexval(rds_getc(s));
    return v;
  }
  return hexval(c1) * 16 + hexval(c2);
}

static int rds_byte_tok(rds_t *s)
{
  return hexval(rds_getc(s)) * 16 + hexval(rds_getc(s));
}

static int64_t rds_int_tok(rds_t *s)
{
  int64_t v = 0;
  int neg = 0, c = rds_getc(s);
  if (c == '-' || c == '+') { neg = (c == '-'); c = rds_getc(s); }
  while (c >= '0' && c <= '9') {
    v = v * 10 + (c - '0');
    c = rds_getc(s);
  }
  if (c >= 0) s->p--;                            /* unget terminator */
  return neg ? -v : v;
}

static size_t rds_size_tok(rds_t *s)
{
  int64_t n = rds_int_tok(s);
  if (n < 0 || rds_getc(s) != ':') return 0;     /* postpone failure */
  return (size_t)n;
}

static double rds_real_tok(rds_t *s)
{
  char buf[64];
  size_t n = 0;
  int c;
  while ((c = *s->p ? (unsigned char)*s->p : -1) >= 0
         && (c == '-' || c == '+' || c == '.'
             || (c >= '0' && c <= '9')
             || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))) {
    if (n + 1 < sizeof(buf)) buf[n++] = (char)c;
    s->p++;
  }
  buf[n] = '\0';
  if (!strcmp(buf, "+inf.0")) return HUGE_VAL;
  if (!strcmp(buf, "-inf.0")) return -HUGE_VAL;
  if (!strcmp(buf, "+nan.0") || !strcmp(buf, "-nan.0")
      || !strcmp(buf, "nan.0"))
    return HUGE_VAL - HUGE_VAL;
  return strtod(buf, NULL);
}

static obj_t rds_sexp_rec(rds_t *s);

static obj_t *rds_elts(rds_t *s, size_t n)
{
  obj_t *elts = (obj_t *)malloc((n ? n : 1) * sizeof(obj_t));
  size_t i;
  if (!elts) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  /* Skint's serialized format terminates every element with ';',
     which is also what terminates a 'j' real token's text */
  for (i = 0; i < n; i++) { elts[i] = rds_sexp_rec(s); (void)rds_getc(s); }
  return elts;
}

static size_t hvector_esz(int t)
{
  size_t esz = 1;                                 /* 0,1 and 32..39 */
  if (t == 2 || t == 3) esz = 2;
  else if (t == 4 || t == 5) esz = 4;
  else if (t == 6 || t == 7) esz = 8;
  else if (t == 10) esz = sizeof(float);
  else if (t == 11) esz = sizeof(double);
  return esz;
}

typedef struct strpay_s { int32_t len; int32_t chars[1]; } strpay_t;
typedef struct bvpay_s  { int32_t len; uint8_t bytes[1]; } bvpay_t;
typedef struct hvpay_s  { int32_t tcode; int32_t len; uint8_t data[1]; }
  hvpay_t;

static obj_t rds_sexp_rec(rds_t *s)
{
  int c = rds_getc(s);
  switch (c) {
    case 'f': return SCM_FALSE;
    case 't': return SCM_TRUE;
    case 'n': return SCM_NULL;
    case 'c': return ((obj_t)(uint32_t)rds_char_tok(s) << 8) | (obj_t)9;
    case 'i': return mk_fixnum(rds_int_tok(s));
    case 'j': return mk_flonum(rds_real_tok(s));
    case 'p': {
      obj_t a = rds_sexp_rec(s);
      obj_t b;
      (void)rds_getc(s);                    /* ';' after car */
      b = rds_sexp_rec(s);
      (void)rds_getc(s);                    /* ';' after cdr */
      obj_t *cell = static_block(SCM_PAIR_HDR, 2);
      cell[0] = a;
      cell[1] = b;
      return (obj_t)(uintptr_t)cell;
    }
    case 'l': {
      size_t n = rds_size_tok(s), i;
      obj_t *elts = rds_elts(s, n);
      obj_t lst = SCM_NULL;
      for (i = n; i-- > 0;) {
        obj_t *cell = static_block(SCM_PAIR_HDR, 2);
        cell[0] = elts[i];
        cell[1] = lst;
        lst = (obj_t)(uintptr_t)cell;
      }
      free(elts);
      return lst;
    }
    case 'v': {
      size_t n = rds_size_tok(s), i;
      obj_t *elts = rds_elts(s, n);
      obj_t *cell = static_block(SCM_HDR(n, MTAG_VECTOR), n);
      for (i = 0; i < n; i++) cell[i] = elts[i];
      free(elts);
      return (obj_t)(uintptr_t)cell;
    }
    case 's': {
      size_t n = rds_size_tok(s), i;
      strpay_t *pay = (strpay_t *)malloc(sizeof(strpay_t)
                                         + (n ? n - 1 : 0) * 4);
      if (!pay) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
      pay->len = (int32_t)n;
      for (i = 0; i < n; i++) pay->chars[i] = rds_char_tok(s);
      return native_obj(&string_cxtype, pay);
    }
    case 'y': {
      size_t n = rds_size_tok(s), i;
      char *buf = (char *)malloc(n + 1);
      obj_t sym;
      if (!buf) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
      for (i = 0; i < n; i++) buf[i] = (char)rds_char_tok(s);
      buf[n] = '\0';
      sym = intern_bytes(buf, n);
      free(buf);
      return sym;
    }
    case 'b': {
      size_t n = rds_size_tok(s), i;
      bvpay_t *pay = (bvpay_t *)malloc(sizeof(bvpay_t) + (n ? n - 1 : 0));
      if (!pay) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
      pay->len = (int32_t)n;
      for (i = 0; i < n; i++) pay->bytes[i] = (uint8_t)rds_byte_tok(s);
      return native_obj(&bytevector_cxtype, pay);
    }
    case 'h': {
      size_t n = rds_size_tok(s), i;
      int t = (int)rds_int_tok(s);
      size_t esz;
      hvpay_t *pay;
      if (rds_getc(s) != ':') return SCM_EOF;
      esz = hvector_esz(t);
      pay = (hvpay_t *)malloc(sizeof(hvpay_t) + (n ? n * esz - 1 : 0));
      if (!pay) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
      pay->tcode = t;
      pay->len = (int32_t)n;
      for (i = 0; i < n; i++) {
        uint8_t *ep = &pay->data[i * esz];
        switch (t) {
          case 0: *(uint8_t *)ep  = (uint8_t)rds_byte_tok(s); break;
          case 1: *(int8_t *)ep   = (int8_t)rds_int_tok(s); break;
          case 2: *(uint16_t *)ep = (uint16_t)rds_int_tok(s); break;
          case 3: *(int16_t *)ep  = (int16_t)rds_int_tok(s); break;
          case 4: *(uint32_t *)ep = (uint32_t)rds_int_tok(s); break;
          case 5: *(int32_t *)ep  = (int32_t)rds_int_tok(s); break;
          case 6: *(uint64_t *)ep = (uint64_t)rds_int_tok(s); break;
          case 7: *(int64_t *)ep  = rds_int_tok(s); break;
          case 10: { float f = (float)rds_real_tok(s);
                     *(float *)ep = f; } break;
          case 11: { double d = rds_real_tok(s);
                     *(double *)ep = d; } break;
          default: *(uint8_t *)ep = (uint8_t)rds_byte_tok(s); break;
        }
        if (t > 0 && t < 32) (void)rds_getc(s);   /* ';' separator */
      }
      return native_obj(&hvector_cxtype, pay);
    }
    case 'z': {
      obj_t a = rds_sexp_rec(s);
      obj_t *cell;
      (void)rds_getc(s);                    /* ';' after element */
      cell = static_block(SCM_BOX_HDR, 1);
      cell[0] = a;
      return (obj_t)(uintptr_t)cell;
    }
    default: return SCM_EOF;
  }
  return SCM_EOF;
}

obj_t deserialize_sexp(void *cstr, void *r, void *hp)
{
  rds_t s;
  (void)r;                          /* literals go to the static area */
  (void)hp;
  ensure_init();
  s.p = (const char *)cstr;
  return rds_sexp_rec(&s);
}

/* ------------------------------------------------------------------ */
/* rest-argument packing                                               */

/* args are a0 plus r[0..rc-2]; the arguments from index req on
   (that is, r[req-1..rc-2]) become a proper list of pairs allocated
   downward from hp.  Returns the new hp. */
void *build_rest_list(obj_t a0, void *r, void *hp, int32_t rc, int32_t req)
{
  obj_t *regs = (obj_t *)(void *)r;
  obj_t lst = SCM_NULL;
  unsigned char *p = (unsigned char *)hp;
  int32_t i, n = rc - req;
  ensure_init();
  if (n <= 0) return hp;
  if ((size_t)(p - (unsigned char *)heap_limit)
      < (size_t)n * 3 * sizeof(obj_t)) {
    if (regs) regs[rc - 1] = a0;          /* protect a0 across the GC */
    p = (unsigned char *)collect(r, regs ? rc : 0, hp, 3 * n);
    a0 = regs ? regs[rc - 1] : a0;
  }
  for (i = rc - 1; i >= req; i--) {
    obj_t *cell;
    p -= 3 * sizeof(obj_t);
    cell = (obj_t *)(void *)(p + sizeof(obj_t));
    *(obj_t *)(void *)p = SCM_PAIR_HDR;
    cell[0] = (i == 0) ? a0 : regs[i - 1];
    cell[1] = lst;
    lst = (obj_t)(uintptr_t)cell;
  }
  return p;
}

/* ------------------------------------------------------------------ */
/* cold error paths                                                    */

void *arity_error(void *clo, int32_t rc, int32_t expected)
{
  fprintf(stderr,
          "scmrt: arity error: closure %p called with %d argument(s),"
          " expected %d\n",
          clo, (int)rc, (int)expected);
  exit(1);
  return NULL;
}

void *type_error(obj_t bad_obj, int32_t expected_code)
{
  fprintf(stderr,
          "scmrt: type error: obj 0x%llx does not satisfy type code %d\n",
          (unsigned long long)bad_obj, (int)expected_code);
  exit(1);
  return NULL;
}

/* ------------------------------------------------------------------ */
/* eqv? and equal?                                                     */

int32_t eqv_p(obj_t a, obj_t b)
{
  if (a == b) return 1;
  if (is_flonum(a) && is_flonum(b))
    return flo_val(a) == flo_val(b) ? 1 : 0;
  return 0;
}

/* Skint's isequal (n.c) does a bounded naive walk first and then a
   sharing-aware comparison; the naive walk alone is exponential on
   shared (DAG-shaped) structure, which is what the R7RS `equal`
   benchmark builds.  We instead memoize the pointer pairs already
   under comparison: meeting the same pair again is success.  That
   is sound here because a failed subcomparison fails the whole
   query at once, and it makes shared structure linear and cyclic
   structure terminate (coinductive equal?, as in Skint). */
typedef struct { obj_t a, b; } eqpair_t;
static eqpair_t *eq_tab;
static size_t eq_cap, eq_len;

static int eq_seen(obj_t a, obj_t b)
{
  size_t h, i;
  if (!eq_tab) {
    eq_cap = 1024;
    eq_tab = (eqpair_t *)calloc(eq_cap, sizeof(eqpair_t));
    if (!eq_tab) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  }
  if ((eq_len + 1) * 2 > eq_cap) {
    eqpair_t *nt;
    size_t ncap = eq_cap * 2, j;
    nt = (eqpair_t *)calloc(ncap, sizeof(eqpair_t));
    if (!nt) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
    for (j = 0; j < eq_cap; j++) {
      if (eq_tab[j].a || eq_tab[j].b) {
        size_t k = (size_t)(((eq_tab[j].a >> 4) ^ (eq_tab[j].b >> 7))
                            * (obj_t)0x9E3779B97F4A7C15ULL) & (ncap - 1);
        while (nt[k].a || nt[k].b) k = (k + 1) & (ncap - 1);
        nt[k] = eq_tab[j];
      }
    }
    free(eq_tab);
    eq_tab = nt;
    eq_cap = ncap;
  }
  h = (size_t)(((a >> 4) ^ (b >> 7)) * (obj_t)0x9E3779B97F4A7C15ULL)
      & (eq_cap - 1);
  i = h;
  for (;;) {
    if (!eq_tab[i].a && !eq_tab[i].b) {
      eq_tab[i].a = a;
      eq_tab[i].b = b;
      eq_len++;
      return 0;
    }
    if (eq_tab[i].a == a && eq_tab[i].b == b) return 1;
    i = (i + 1) & (eq_cap - 1);
  }
  /* unreachable: the loop above only exits by returning.  WCPL asks a
     non-void function to end in an explicit return and does not reason
     about for(;;), so this is for it. [cco] */
  return 0;
}

static int rt_equal_rec(obj_t a, obj_t b, int depth)
{
  if (depth > 1000000) return 0;
  for (;;) {
    obj_t ha, hb;
    if (a == b) return 1;
    if (!is_objptr(a) || !is_objptr(b)) return eqv_p(a, b);
    ha = ((obj_t *)(uintptr_t)a)[-1];
    hb = ((obj_t *)(uintptr_t)b)[-1];
    if ((ha & 1) && (hb & 1)) {
      size_t n, j;
      if (ha != hb) return 0;
      if (eq_seen(a, b)) return 1;
      n = (size_t)(ha >> 3);
      if (((ha >> 1) & 3) == MTAG_PACKED && n == 2) {   /* pair spine */
        obj_t *ca = (obj_t *)(uintptr_t)a;
        obj_t *cb = (obj_t *)(uintptr_t)b;
        if (!rt_equal_rec(ca[0], cb[0], depth + 1)) return 0;
        a = ca[1];
        b = cb[1];
        continue;
      }
      j = ((ha >> 1) & 3) == MTAG_CLOSURE ? 1 : 0;
      for (; j < n; j++)
        if (!rt_equal_rec(((obj_t *)(uintptr_t)a)[j],
                          ((obj_t *)(uintptr_t)b)[j], depth + 1))
          return 0;
      return 1;
    }
    if (!(ha & 1) && !(hb & 1)) {                        /* natives */
      void *pa = (void *)(uintptr_t)((obj_t *)(uintptr_t)a)[0];
      void *pb = (void *)(uintptr_t)((obj_t *)(uintptr_t)b)[0];
      if (ha != hb) return 0;                            /* diff. type */
      if (ha == (obj_t)(uintptr_t)&string_cxtype) {
        strpay_t *sa = (strpay_t *)pa, *sb = (strpay_t *)pb;
        int32_t i;
        if (sa->len != sb->len) return 0;
        for (i = 0; i < sa->len; i++)
          if (sa->chars[i] != sb->chars[i]) return 0;
        return 1;
      }
      if (ha == (obj_t)(uintptr_t)&bytevector_cxtype) {
        bvpay_t *ba = (bvpay_t *)pa, *bb = (bvpay_t *)pb;
        int32_t i;
        if (ba->len != bb->len) return 0;
        for (i = 0; i < ba->len; i++)
          if (ba->bytes[i] != bb->bytes[i]) return 0;
        return 1;
      }
      if (ha == (obj_t)(uintptr_t)&hvector_cxtype) {
        hvpay_t *ha2 = (hvpay_t *)pa, *hb2 = (hvpay_t *)pb;
        size_t bytes, i;
        if (ha2->tcode != hb2->tcode || ha2->len != hb2->len) return 0;
        bytes = (size_t)ha2->len * hvector_esz(ha2->tcode);
        for (i = 0; i < bytes; i++)
          if (ha2->data[i] != hb2->data[i]) return 0;
        return 1;
      }
      return pa == pb;                          /* opaque: identity */
    }
    return 0;
  }
  return 0;
}

int32_t equal_p(obj_t a, obj_t b)
{
  int32_t r;
  if (eq_tab) memset(eq_tab, 0, eq_cap * sizeof(eqpair_t));
  eq_len = 0;
  r = rt_equal_rec(a, b, 0);
  if (eq_tab) memset(eq_tab, 0, eq_cap * sizeof(eqpair_t));
  eq_len = 0;
  return r;
}

/* ------------------------------------------------------------------ */
/* strings and text output (support for the $scmn/$scmi macro libs)   */
/*                                                                    */
/* Strings are Native wrappers around a malloc'd strpay_t            */
/* ({int32 len; int32 chars[]}, one int32 codepoint per char).  The   */
/* wrapper itself is an ordinary 2-word heap block allocated by       */
/* compiled code; it needs to know the string cxtype address to use   */
/* as its header word, hence string_type.  The collector finalizes    */
/* dead wrappers through cxtype string_cxtype.free (= free).          */

obj_t string_type(void)
{
  return (obj_t)(uintptr_t)&string_cxtype;
}

void *make_string_payload(int32_t len, int32_t fill)
{
  strpay_t *p = (strpay_t *)malloc(sizeof(strpay_t)
                                   + (len > 0 ? (size_t)(len - 1) * 4 : 0));
  int32_t i;
  if (!p) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  p->len = len;
  for (i = 0; i < len; i++) p->chars[i] = fill;
  return (void *)p;
}

/* ------------------------------------------------------------------ */
/* ports (S3): Native wrappers over a malloc'd portpay_t.  File     */
/* ports wrap a FILE*; string ports read from / accumulate into a  */
/* strpay_t codepoint buffer.  The standard ports are immortal     */
/* static-area wrappers created lazily.                            */

#define PORT_CLOSED 0
#define PORT_FIN    1
#define PORT_FOUT   2
#define PORT_SIN    3
#define PORT_SOUT   4
/* input over a bytevector, widened into a codepoint buffer the port
   owns.  A byte is a codepoint below 256, which is the convention the
   shadow (scheme base) already uses: it defines read-u8 as read-char
   followed by char->integer, so a bytevector port reads as a character
   port and needs no byte-specific path of its own.  [cco] */
#define PORT_BIN    5
/* output collecting bytes.  It behaves exactly as PORT_SOUT in the
   write path, and exists as its own kind only so that port_flags can
   report it as binary: binary-port? asks, and a bytevector port that
   claimed to be textual would be a wrong answer rather than a missing
   one.  [cco] */
#define PORT_BOUT   6

typedef struct portpay_s {
  int32_t kind;
  FILE *fp;
  strpay_t *str;
  int32_t pos;
  int32_t cap;
  int32_t peek;
  int32_t has_peek;
} portpay_t;

static void port_free(void *vp)
{
  portpay_t *p = (portpay_t *)vp;
  if (!p) return;
  if (p->fp && p->kind == PORT_FIN) fclose(p->fp);
  if (p->fp && p->kind == PORT_FOUT) fclose(p->fp);
  if (p->str && (p->kind == PORT_SOUT || p->kind == PORT_BIN
                 || p->kind == PORT_BOUT)) free(p->str);
  free(p);
}

static portpay_t *port_of(obj_t o)
{
  return (portpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
}

/* append one codepoint to a string-output port's buffer */
static void spush_cp(portpay_t *p, int32_t cp)
{
  if (p->str->len >= p->cap) {
    int32_t ncap = p->cap ? p->cap * 2 : 64;
    strpay_t *ns = (strpay_t *)realloc(p->str,
                       sizeof(strpay_t) + (size_t)(ncap - 1) * 4);
    if (!ns) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
    p->str = ns;
    p->cap = ncap;
  }
  p->str->chars[p->str->len++] = cp;
}

/* print sink: a FILE* (stdout/stderr/file port) or, when sp is
   set, a string-output port accumulating codepoints */
typedef struct prsink_s {
  FILE *fp;
  portpay_t *sp;
} prsink_t;

static void pr_cp(prsink_t *sk, int32_t cp)
{
  if (sk->sp) spush_cp(sk->sp, cp);
  else putc(cp < 128 ? (int)cp : '?', sk->fp);
}

static void pr_str(prsink_t *sk, const char *s)
{
  if (sk->sp) {
    while (*s) spush_cp(sk->sp, (int32_t)(uint8_t)*s++);
  } else {
    fputs(s, sk->fp);
  }
}

/* Skint-style shortest-round-trip flonum formatting (defined
   with the S2 helpers below) */
static void fmt_double(char *buf, double d);

/* Minimal text-output rendering of the core object graph (fixnums,
   flonums, booleans, chars, strings, pairs, vectors, boxes, null) to
   stdout.  writep selects write-style (quoted strings, #\chars). */
static void pr_sink(prsink_t *sk, obj_t o, int writep)
{
  if (o == SCM_FALSE) { pr_str(sk, "#f"); return; }
  if (o == SCM_TRUE)  { pr_str(sk, "#t"); return; }
  if (o == SCM_NULL)  { pr_str(sk, "()"); return; }
  if (is_fixnum(o)) {                                  /* fixnum */
    /* getim0s: sign-decode the 30-bit payload in the low word */
    { char nb[24];
      sprintf(nb, "%d",
              (int)(((((int32_t)o >> 2) & 0x3fffffff) ^ 0x20000000)
                    - 0x20000000));
      pr_str(sk, nb); }
    return;
  }
  if (!(o & (obj_t)0xffffffff00000000ULL) && (o & 3) == 1) {  /* immediate: high 32 bits zero, isimm */
    obj_t itag = (o >> 2) & 63;
    if (itag == 2) {                                   /* char */
      int32_t c = (int32_t)(o >> 8);
      if (writep) {
        if (c == 10) pr_str(sk, "#\\newline");
        else if (c == 32) pr_str(sk, "#\\space");
        else if (c >= 33 && c < 127) { char nb[8]; sprintf(nb, "#\\%c", (int)c); pr_str(sk, nb); }
        else { char nb[16]; sprintf(nb, "#\\x%x", (unsigned)c); pr_str(sk, nb); }
      }
      else if (c < 128) pr_cp(sk, (int)c);
      else pr_cp(sk, '?');
      return;
    }
    if (itag == 4) {                                   /* symbol */
      size_t idx = (size_t)(o >> 8);
      if (idx < rt_syms_len) pr_str(sk, rt_syms[idx]);
      else pr_str(sk, "#<symbol>");
      return;
    }
    if (itag == 5) { pr_str(sk, "#<void>"); return; }
    if (itag == 7) { pr_str(sk, "#<eof>"); return; }
    pr_str(sk, "#<imm>");
    return;
  }
  if (is_objptr(o)) {
    obj_t *cell = (obj_t *)(uintptr_t)o;
    obj_t h = cell[-1];
    if (!(h & 1)) {                                    /* Native */
      if (h == (obj_t)(uintptr_t)&string_cxtype) {
        strpay_t *s = (strpay_t *)(uintptr_t)cell[0];
        int32_t i;
        if (writep) pr_cp(sk, '"');
        for (i = 0; i < s->len; i++) {
          int32_t c = s->chars[i];
          if (writep && (c == '"' || c == '\\')) pr_cp(sk, '\\');
          if (c < 128) pr_cp(sk, (int)c); else pr_cp(sk, '?');
        }
        if (writep) pr_cp(sk, '"');
        return;
      }
      if (h == (obj_t)(uintptr_t)&bytevector_cxtype) {
        bvpay_t *b = (bvpay_t *)(uintptr_t)cell[0];
        int32_t i;
        pr_str(sk, "#u8(");
        for (i = 0; i < b->len; i++) {
          char nb[8];
          if (i) pr_cp(sk, ' ');
          sprintf(nb, "%u", (unsigned)b->bytes[i]);
          pr_str(sk, nb);
        }
        pr_cp(sk, ')');
        return;
      }
      if (h == (obj_t)(uintptr_t)&port_cxtype) {
        pr_str(sk, "#<port>");
        return;
      }
      pr_str(sk, "#<Native>");
      return;
    }
    if (h == SCM_PAIR_HDR) {
      obj_t t = o;
      pr_cp(sk, '(');
      for (;;) {
        obj_t *tc = (obj_t *)(uintptr_t)t;
        pr_sink(sk, tc[0], writep);
        t = tc[1];
        if (t == SCM_NULL) break;
        if (is_objptr(t) && ((obj_t *)(uintptr_t)t)[-1] == SCM_PAIR_HDR) {
          pr_cp(sk, ' ');
          continue;
        }
        pr_str(sk, " . ");
        pr_sink(sk, t, writep);
        break;
      }
      pr_cp(sk, ')');
      return;
    }
    if (((h >> 1) & 3) == MTAG_VECTOR) {
      size_t n = (size_t)(h >> 3), j;
      pr_str(sk, "#(");
      for (j = 0; j < n; j++) {
        if (j) pr_cp(sk, ' ');
        pr_sink(sk, cell[j], writep);
      }
      pr_cp(sk, ')');
      return;
    }
    if (h == SCM_BOX_HDR) {
      pr_str(sk, "#<box ");
      pr_sink(sk, cell[0], writep);
      pr_cp(sk, '>');
      return;
    }
    pr_str(sk, "#<obj>");
    return;
  }
  {                                                    /* flonum */
    char buf[64];
    fmt_double(buf, flo_val(o));
    pr_str(sk, buf);
    return;
  }
}

void display_obj(obj_t o)
{
  prsink_t sk;
  sk.fp = stdout;
  sk.sp = NULL;
  pr_sink(&sk, o, 0);
}

void write_obj(obj_t o)
{
  prsink_t sk;
  sk.fp = stdout;
  sk.sp = NULL;
  pr_sink(&sk, o, 1);
}

/* Cold path for checked accessors (the $scmi:car family and its
   future siblings): one generic reporter for the whole
   "argument is not a/an X" class.  WHAT is a static C string
   (passed by pointer from a MARV data segment), BAD the
   offending value.  Like Skint: report and exit(1) -- not a
   Scheme exception, not a crash.  Only reached from cold
   branches, so regular instruction streams stay free of
   non-tail calls. */
void *arg_error(obj_t bad, const char *what)
{
  prsink_t sk;
  fprintf(stderr, "scmrt: argument is not %s: ", what);
  sk.fp = stderr;
  sk.sp = NULL;
  pr_sink(&sk, bad, 1);
  fprintf(stderr, "\n");
  exit(1);
  return NULL;
}

/* the (skint) `error` builtin as DS materializes it for libraries
   that import it from (skint): report the message and exit, the
   compiled-code bottom line (no host exception machinery) */
void *error_raise(obj_t msg)
{
  prsink_t sk;
  fprintf(stderr, "Error: ");
  sk.fp = stderr;
  sk.sp = NULL;
  pr_sink(&sk, msg, 0);
  fprintf(stderr, "\n");
  exit(1);
  return NULL;
}

/* ------------------------------------------------------------------ */
/* S2 support: bytevectors, symbol<->string, number->string, frexp    */
/*                                                                    */
/* number->string's digit generation lives here as a library          */
/* conversion: the compiled code passes the number (and radix) and    */
/* wraps the returned malloc'd payload in a $scmn:hpushptr block.     */

static int64_t fx_val(obj_t o)
{
  return (int64_t)(((((int32_t)o >> 2) & 0x3fffffff) ^ 0x20000000)
                   - 0x20000000);
}

static strpay_t *strpay_from_ascii(const char *s, size_t n)
{
  strpay_t *p = (strpay_t *)malloc(sizeof(strpay_t)
                                   + (n ? (n - 1) * 4 : 0));
  size_t i;
  if (!p) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  p->len = (int32_t)n;
  for (i = 0; i < n; i++) p->chars[i] = (int32_t)(uint8_t)s[i];
  return p;
}

obj_t bytevector_type(void)
{
  return (obj_t)(uintptr_t)&bytevector_cxtype;
}

void *make_bytevector_payload(int32_t len)
{
  bvpay_t *p = (bvpay_t *)malloc(sizeof(bvpay_t) + (len > 0 ? len - 1 : 0));
  if (!p) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  p->len = len;
  memset((char *)(void *)p + 4, 0, (size_t)(len > 0 ? len : 0));
  return (void *)p;
}

int32_t is_bytevector(obj_t o)
{
  if (!is_objptr(o)) return 0;
  return ((obj_t *)(uintptr_t)o)[-1]
         == (obj_t)(uintptr_t)&bytevector_cxtype;
}

int32_t bytevector_length(obj_t o)
{
  bvpay_t *p = (bvpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
  return p->len;
}

int32_t bytevector_u8_ref(obj_t o, int32_t i)
{
  bvpay_t *p = (bvpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
  return (int32_t)p->bytes[i];
}

static int utf8_decode(const char *s, size_t n, int32_t *out)
{
  /* decode the symbol name bytes into codepoints; the count is
     returned via the produced payload length, here directly */
  size_t i = 0;
  int32_t len = 0;
  while (i < n) {
    uint32_t c = (uint8_t)s[i];
    size_t k = 1;
    if (c >= 0xf0)      { c &= 7;  k = 4; }
    else if (c >= 0xe0) { c &= 15; k = 3; }
    else if (c >= 0xc0) { c &= 31; k = 2; }
    {
      size_t j;
      for (j = 1; j < k && i + j < n; j++)
        c = (c << 6) | ((uint8_t)s[i + j] & 63);
    }
    out[len++] = (int32_t)c;
    i += k;
  }
  return len;
}

void *symbol_to_string(obj_t o)
{
  const char *name = rt_syms[(size_t)(o >> 8)];
  size_t n = strlen(name);
  strpay_t *p = (strpay_t *)malloc(sizeof(strpay_t)
                                   + (n ? (n - 1) * 4 : 0));
  if (!p) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  p->len = utf8_decode(name, n, p->chars);
  return (void *)p;
}

obj_t string_to_symbol(obj_t o)
{
  strpay_t *p = (strpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
  char *buf = (char *)malloc((size_t)(p->len > 0 ? p->len : 1) * 4 + 1);
  size_t n = 0;
  int32_t i;
  obj_t s;
  if (!buf) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  for (i = 0; i < p->len; i++) {
    uint32_t c = (uint32_t)p->chars[i];
    if (c < 0x80) {
      buf[n++] = (char)c;
    } else if (c < 0x800) {
      buf[n++] = (char)(0xc0 | (c >> 6));
      buf[n++] = (char)(0x80 | (c & 63));
    } else if (c < 0x10000) {
      buf[n++] = (char)(0xe0 | (c >> 12));
      buf[n++] = (char)(0x80 | ((c >> 6) & 63));
      buf[n++] = (char)(0x80 | (c & 63));
    } else {
      buf[n++] = (char)(0xf0 | (c >> 18));
      buf[n++] = (char)(0x80 | ((c >> 12) & 63));
      buf[n++] = (char)(0x80 | ((c >> 6) & 63));
      buf[n++] = (char)(0x80 | (c & 63));
    }
  }
  s = intern_bytes(buf, n);
  free(buf);
  return s;
}

/* Skint-style flonum formatting: the shortest decimal that
   round-trips (found via %.*e at increasing precision), in
   fixed notation when the decimal exponent is in [-4, 15],
   scientific (d[.ddd]e<exp>, no '+', no leading zeros)
   otherwise; integral fixed values get a trailing .0 */
static void fmt_double(char *buf, double d)
{
  char tmp[64], digs[24];
  int prec, e = 0, nd = 0, neg = 0;
  char *p;
  if (d != d) { strcpy(buf, "+nan.0"); return; }
  if (d == HUGE_VAL) { strcpy(buf, "+inf.0"); return; }
  if (d == -HUGE_VAL) { strcpy(buf, "-inf.0"); return; }
  if (d == 0.0) { strcpy(buf, signbit(d) ? "-0.0" : "0.0"); return; }
  if (d < 0) { neg = 1; d = -d; }
  for (prec = 1; prec <= 17; prec++) {
    sprintf(tmp, "%.*e", prec - 1, d);
    if (strtod(tmp, NULL) == d) break;
  }
  /* tmp is like "2.500e+10": collect digits and the exponent */
  p = tmp;
  while (*p && *p != 'e') {
    if (*p >= '0' && *p <= '9') digs[nd++] = *p;
    p++;
  }
  e = atoi(p + 1);
  digs[nd] = '\0';
  p = buf;
  if (neg) *p++ = '-';
  if (e >= -4 && e <= 15) {
    if (e >= 0) {
      int i;
      for (i = 0; i <= e; i++) *p++ = (i < nd) ? digs[i] : '0';
      if (nd > e + 1) {
        *p++ = '.';
        for (i = e + 1; i < nd; i++) *p++ = digs[i];
      } else {
        *p++ = '.'; *p++ = '0';
      }
    } else {
      int i;
      *p++ = '0'; *p++ = '.';
      for (i = 0; i < -e - 1; i++) *p++ = '0';
      for (i = 0; i < nd; i++) *p++ = digs[i];
    }
  } else {
    int i;
    *p++ = digs[0];
    if (nd > 1) {
      *p++ = '.';
      for (i = 1; i < nd; i++) *p++ = digs[i];
    }
    *p++ = 'e';
    if (e < 0) { *p++ = '-'; e = -e; }
    sprintf(p, "%d", e);
    return;
  }
  *p = '\0';
}

static void fmt_radix_int(char *buf, int64_t v, int radix)
{
  char tmp[40];
  uint64_t uv = (v < 0) ? (uint64_t)(-(v + 1)) + 1 : (uint64_t)v;
  int n = 0, i = 0;
  if (uv == 0) tmp[n++] = '0';
  while (uv != 0) {
    uint32_t d = (uint32_t)(uv % (uint64_t)radix);
    tmp[n++] = (char)(d < 10 ? '0' + d : 'a' + (d - 10));
    uv /= (uint64_t)radix;
  }
  if (v < 0) buf[i++] = '-';
  while (n > 0) buf[i++] = tmp[--n];
  buf[i] = '\0';
}

void *number_to_string(obj_t o, obj_t ro)
{
  char buf[1200];
  int radix = 10;
  if (is_fixnum(ro)) {
    int64_t r = fx_val(ro);
    if (r >= 2 && r <= 36) radix = (int)r;
  }
  buf[0] = '\0';
  if (is_fixnum(o)) {
    fmt_radix_int(buf, fx_val(o), radix);
  } else if (is_flonum(o)) {
    double d = flo_val(o);
    if (radix != 10 && d == d && d != HUGE_VAL && d != -HUGE_VAL
        && d == trunc(d) && fabs(d) <= 9007199254740992.0) {
      fmt_radix_int(buf, (int64_t)d, radix);
      strcat(buf, ".0");
    } else {
      fmt_double(buf, d);
    }
  } else {
    strcpy(buf, "0");
  }
  return (void *)strpay_from_ascii(buf, strlen(buf));
}

obj_t frexp_into_box(obj_t x, obj_t b)
{
  int e = 0;
  double m = frexp(flo_val(x), &e);
  ((obj_t *)(uintptr_t)b)[0] = mk_fixnum((int64_t)e);
  return mk_flonum(m);
}

double dpow(double a, double b)
{
  return pow(a, b);
}

/* ------------------------------------------------------------------ */
/* S3: ports and OS services                                          */
/*                                                                    */
/* File and string ports share the portpay_t layout declared with    */
/* the print sink above.  Payloads created here are wrapped by       */
/* compiled code ($scmn:hpushptr over $scmrt:port_type), except      */
/* the immortal standard ports, which live in the static area.       */

/* string obj -> malloc'd NUL-terminated UTF-8 bytes (filenames,
   environment names, %system commands) */
static char *str_obj_bytes(obj_t o)
{
  strpay_t *p = (strpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
  char *buf = (char *)malloc((size_t)(p->len > 0 ? p->len : 1) * 4 + 1);
  size_t n = 0;
  int32_t i;
  if (!buf) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  for (i = 0; i < p->len; i++) {
    uint32_t c = (uint32_t)p->chars[i];
    if (c < 0x80) {
      buf[n++] = (char)c;
    } else if (c < 0x800) {
      buf[n++] = (char)(0xc0 | (c >> 6));
      buf[n++] = (char)(0x80 | (c & 63));
    } else if (c < 0x10000) {
      buf[n++] = (char)(0xe0 | (c >> 12));
      buf[n++] = (char)(0x80 | ((c >> 6) & 63));
      buf[n++] = (char)(0x80 | (c & 63));
    } else {
      buf[n++] = (char)(0xf0 | (c >> 18));
      buf[n++] = (char)(0x80 | ((c >> 12) & 63));
      buf[n++] = (char)(0x80 | ((c >> 6) & 63));
      buf[n++] = (char)(0x80 | (c & 63));
    }
  }
  buf[n] = '\0';
  return buf;
}

/* string->number (library conversion): integers in the 30-bit
   fixnum range become fixnums, other numeric values become
   flonums (this runtime has no bignums), non-numbers become #f.
   Non-allocating: the result is always an immediate. */
obj_t string_to_number(obj_t o, obj_t ro)
{
  char *s = str_obj_bytes(o);
  const char *p = s;
  int radix = 10;
  int neg = 0, any = 0, big = 0;
  int64_t v = 0;
  double d;
  obj_t res = (obj_t)0;                 /* #f */
  if (is_fixnum(ro)) {
    int64_t r = fx_val(ro);
    if (r >= 2 && r <= 36) radix = (int)r;
  }
  if (p[0] == '#' && (p[1] == 'b' || p[1] == 'o' || p[1] == 'd' || p[1] == 'x')) {
    radix = (p[1] == 'b') ? 2 : (p[1] == 'o') ? 8 : (p[1] == 'd') ? 10 : 16;
    p += 2;
  }
  if (*p == '+') p++;
  else if (*p == '-') { neg = 1; p++; }
  {
    const char *q = p;
    for (; *q; q++) {
      int c = (unsigned char)*q, dig;
      if (c >= '0' && c <= '9') dig = c - '0';
      else if (c >= 'a' && c <= 'z') dig = c - 'a' + 10;
      else if (c >= 'A' && c <= 'Z') dig = c - 'A' + 10;
      else break;
      if (dig >= radix) break;
      any = 1;
      if (!big) {
        v = v * radix + dig;
        if (v > 536870911LL) big = 1;   /* beyond fixnum: go double */
      }
    }
    if (any && *q == '\0') {
      if (big) {
        double dv = 0;
        for (; *p; p++) {
          int c = (unsigned char)*p, dig;
          if (c >= '0' && c <= '9') dig = c - '0';
          else if (c >= 'a' && c <= 'z') dig = c - 'a' + 10;
          else dig = c - 'A' + 10;
          dv = dv * radix + dig;
        }
        res = mk_flonum(neg ? -dv : dv);
      } else {
        res = mk_fixnum(neg ? -v : v);
      }
      free(s);
      return res;
    }
  }
  /* A leading-dot decimal -- .5, -.5, +.5, .5e2 -- has no digit before
     the integer scan breaks, so `any` stayed 0 and the strtod fallback
     below was skipped and the whole token rejected.  Admit the token
     when it looks like a Scheme decimal: an optional sign (already
     consumed), an optional dot, then a digit.  Testing the shape here
     rather than dropping the guard keeps strtod away from the spellings
     C accepts and Scheme does not, such as inf, nan and infinity. */
  {
    const char *t = p;
    if (*t == '.') t += 1;
    if (*t >= '0' && *t <= '9') any = 1;
  }
  /* C's strtod also reads the hexadecimal form 0x10, which Scheme does
     not: (string->number "0x10") is #f.  The integer scan stops at the
     'x' with a digit already seen, so without this the token would reach
     strtod and come back as 16.0. */
  {
    const char *t = p;
    for (; *t; t += 1) if (*t == 'x' || *t == 'X') { any = 0; break; }
  }
  if (radix == 10 && any) {
    char *end = NULL;
    d = strtod(s, &end);
    if (end && end != s && *end == '\0') res = mk_flonum(d);
  }
  if (!strcmp(s, "+inf.0")) res = mk_flonum(HUGE_VAL);
  else if (!strcmp(s, "-inf.0")) res = mk_flonum(-HUGE_VAL);
  else if (!strcmp(s, "+nan.0") || !strcmp(s, "-nan.0")) res = mk_flonum(HUGE_VAL - HUGE_VAL);
  free(s);
  return res;
}

obj_t port_type(void)
{
  return (obj_t)(uintptr_t)&port_cxtype;
}

static portpay_t *new_portpay(int32_t kind)
{
  portpay_t *p = (portpay_t *)calloc(1, sizeof(portpay_t));
  if (!p) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  port_cxtype.free = &port_free;
  p->kind = kind;
  p->peek = -1;
  return p;
}

/* The three standard-port slots live in a 3-cell block in the STATIC
   area rather than in C variables, and rt_ports holds that block.
   The collector already scans [static_lo, static_bump) word by word as
   a root set, so a replacement port -- which may be a heap object, see
   the setters below -- is forwarded without anything being registered.
   That is the same arrangement rt_command_line and rt_values_tag use:
   an obj_t in a C static whose VALUE is rebased when the region grows,
   and whose address is never taken.
   Not taking the address is what this is for.  register_root wants the
   slot's address, and the only C type a MARV `ptr` parameter has is
   `void *`, which WCPL cannot pass anything to: `&scalar` is "cannot
   take address of expression" (a file-scope scalar becomes a wasm
   global, which has no address), an array decays to "unexpected type",
   and a cast is an "impossible cast" -- while a TYPED pointer
   parameter takes an array fine.  So the C-side register_root calls
   could not be expressed at all on the wasm target, and rooting these
   through the static area removes the need for them. [cco] */
static obj_t rt_ports;

#define RT_PORT_IN  0
#define RT_PORT_OUT 1
#define RT_PORT_ERR 2

static obj_t *port_slots(void)
{
  if (!rt_ports) {
    obj_t *cells = static_block(SCM_HDR(3, MTAG_PACKED), 3);
    rt_ports = (obj_t)(uintptr_t)cells;
  }
  return (obj_t *)(uintptr_t)rt_ports;
}

static obj_t mk_std_port(FILE *fp, int32_t kind)
{
  portpay_t *p;
  ensure_init();
  p = new_portpay(kind);
  p->fp = fp;
  return native_obj(&port_cxtype, (void *)p);
}

obj_t current_input_port(void)
{
  obj_t *s = port_slots();
  if (!s[RT_PORT_IN]) s[RT_PORT_IN] = mk_std_port(stdin, PORT_FIN);
  return s[RT_PORT_IN];
}

obj_t current_output_port(void)
{
  obj_t *s = port_slots();
  if (!s[RT_PORT_OUT]) s[RT_PORT_OUT] = mk_std_port(stdout, PORT_FOUT);
  return s[RT_PORT_OUT];
}

obj_t current_error_port(void)
{
  obj_t *s = port_slots();
  if (!s[RT_PORT_ERR]) s[RT_PORT_ERR] = mk_std_port(stderr, PORT_FOUT);
  return s[RT_PORT_ERR];
}

/* The standard ports can be replaced from Scheme (the shadow
   libraries' with-input-from-port / with-output-to-port and
   friends).  A replacement may be a heap object, and it is rooted by
   sitting in the static-area block that port_slots hands out, which
   the collector scans as part of its static root set -- so there is
   nothing to register here. */
void set_current_input_port(obj_t p)  { port_slots()[RT_PORT_IN] = p; }
void set_current_output_port(obj_t p) { port_slots()[RT_PORT_OUT] = p; }
void set_current_error_port(obj_t p)  { port_slots()[RT_PORT_ERR] = p; }

static int32_t port_kind_p(obj_t o, int32_t a, int32_t b)
{
  int32_t k;
  if (!is_objptr(o)) return 0;
  if (((obj_t *)(uintptr_t)o)[-1] != (obj_t)(uintptr_t)&port_cxtype)
    return 0;
  k = port_of(o)->kind;
  return k == a || k == b;
}

int32_t is_input_port(obj_t o)
{
  return port_kind_p(o, PORT_FIN, PORT_SIN)
         || port_kind_p(o, PORT_BIN, PORT_BIN);
}

int32_t is_output_port(obj_t o)
{
  return port_kind_p(o, PORT_FOUT, PORT_SOUT)
         || port_kind_p(o, PORT_BOUT, PORT_BOUT);
}

void *open_input_file(obj_t o)
{
  char *name = str_obj_bytes(o);
  FILE *fp = fopen(name, "r");
  portpay_t *p;
  if (!fp) {
    fprintf(stderr, "scmrt: cannot open input file: %s\n", name);
    free(name);
    abort();
  }
  free(name);
  p = new_portpay(PORT_FIN);
  p->fp = fp;
  return (void *)p;
}

void *open_output_file(obj_t o)
{
  char *name = str_obj_bytes(o);
  FILE *fp = fopen(name, "w");
  portpay_t *p;
  if (!fp) {
    fprintf(stderr, "scmrt: cannot open output file: %s\n", name);
    free(name);
    abort();
  }
  free(name);
  p = new_portpay(PORT_FOUT);
  p->fp = fp;
  return (void *)p;
}

/* %open-input-file / %open-output-file: NULL payload (= #f in
   the wrapper macro) when the file cannot be opened */
void *try_open_input_file(obj_t o)
{
  char *name = str_obj_bytes(o);
  FILE *fp = fopen(name, "r");
  portpay_t *p;
  free(name);
  if (!fp) return NULL;
  p = new_portpay(PORT_FIN);
  p->fp = fp;
  return (void *)p;
}

void *try_open_output_file(obj_t o)
{
  char *name = str_obj_bytes(o);
  FILE *fp = fopen(name, "w");
  portpay_t *p;
  free(name);
  if (!fp) return NULL;
  p = new_portpay(PORT_FOUT);
  p->fp = fp;
  return (void *)p;
}

void *make_input_string_port(obj_t o)
{
  portpay_t *p = new_portpay(PORT_SIN);
  p->str = (strpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
  p->pos = 0;
  return (void *)p;
}

void *make_output_string_port(void)
{
  portpay_t *p = new_portpay(PORT_SOUT);
  p->str = (strpay_t *)malloc(sizeof(strpay_t));
  if (!p->str) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  p->str->len = 0;
  p->cap = 0;
  return (void *)p;
}

/* open-input-bytevector: widen the bytes into codepoints, which the
   reader path already understands.  The copy is this port's own, and
   port_free releases it; reading the Scheme bytevector in place is not
   an option, because its payload is bytes and chars[] is int32.  [cco] */
/* open-output-bytevector: a string-output port that reports itself as
   binary.  The buffer is codepoints, narrowed to bytes only when
   get-output-bytevector asks.  [cco] */
void *make_output_bytevector_port(void)
{
  portpay_t *p = new_portpay(PORT_BOUT);
  p->str = (strpay_t *)malloc(sizeof(strpay_t));
  if (!p->str) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  p->str->len = 0;
  p->cap = 0;
  return (void *)p;
}

/* %port?: the flag bits the shadow (scheme base) expects, or -1 for a
   value that is not a port.  Bit 1 is input, bit 2 is output, bit 4 is
   binary; port? tests that the answer is a fixnum at all, and
   textual-port? and binary-port? test bit 4.  A file port reports
   textual because the representation does not record which mode it was
   opened in, so there is nothing truthful to report.  [cco] */
int32_t port_flags(obj_t o)
{
  portpay_t *p;
  if (!is_objptr(o)) return -1;
  if (((obj_t *)(uintptr_t)o)[-1] != (obj_t)(uintptr_t)&port_cxtype)
    return -1;
  p = port_of(o);
  switch (p->kind) {
    case PORT_FIN:  return 1;
    case PORT_SIN:  return 1;
    case PORT_BIN:  return 1 | 4;
    case PORT_FOUT: return 2;
    case PORT_SOUT: return 2;
    case PORT_BOUT: return 2 | 4;
    default:        return 0;
  }
  /* unreachable: every case returns, default included.  As in eq_seen,
     WCPL wants the last statement of a non-void function to BE a
     return and does not look inside the switch. [cco] */
  return 0;
}

void *make_input_bytevector_port(obj_t o)
{
  bvpay_t *bv = (bvpay_t *)(uintptr_t)((obj_t *)(uintptr_t)o)[0];
  int32_t n = bv->len, i;
  portpay_t *p = new_portpay(PORT_BIN);
  strpay_t *w = (strpay_t *)malloc(sizeof(strpay_t)
                                   + (n > 0 ? (size_t)(n - 1) * 4 : 0));
  if (!w) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  w->len = n;
  for (i = 0; i < n; i++) w->chars[i] = (int32_t)bv->bytes[i];
  p->str = w;
  p->pos = 0;
  return (void *)p;
}

/* get-output-bytevector: narrow the codepoints back to bytes.  A
   codepoint above 255 means a character was written to a port whose
   contents are bytes, and there is no byte to narrow it to, so it is
   reported rather than truncated into a plausible wrong answer.  [cco] */
void *get_output_bytevector_payload(obj_t o)
{
  portpay_t *p = port_of(o);
  int32_t n = p->str->len, i;
  bvpay_t *r = (bvpay_t *)malloc(sizeof(bvpay_t)
                                 + (n > 0 ? (size_t)(n - 1) : 0));
  if (!r) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  r->len = n;
  for (i = 0; i < n; i++) {
    int32_t cp = p->str->chars[i];
    if (cp < 0 || cp > 255) {
      fprintf(stderr, "scmrt: not a byte in a bytevector port: %ld\n",
              (long)cp);
      exit(1);
    }
    r->bytes[i] = (uint8_t)cp;
  }
  return (void *)r;
}

void *get_output_string_payload(obj_t o)
{
  portpay_t *p = port_of(o);
  int32_t n = p->str->len;
  strpay_t *r = (strpay_t *)malloc(sizeof(strpay_t)
                                   + (n > 0 ? (size_t)(n - 1) * 4 : 0));
  if (!r) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  r->len = n;
  memcpy((char *)(void *)r + 4, (char *)(void *)p->str + 4,
         (size_t)n * 4);
  return (void *)r;
}

void close_port(obj_t o)
{
  portpay_t *p = port_of(o);
  if ((p->kind == PORT_FIN || p->kind == PORT_FOUT) && p->fp != NULL) {
    fclose(p->fp);
    p->fp = NULL;
  }
  p->kind = PORT_CLOSED;
}

void flush_port(obj_t o)
{
  portpay_t *p = port_of(o);
  if (p->kind == PORT_FOUT && p->fp != NULL) fflush(p->fp);
}

static int32_t port_getc(portpay_t *p)
{
  if (p->has_peek) {
    p->has_peek = 0;
    return p->peek;
  }
  if (p->kind == PORT_SIN || p->kind == PORT_BIN) {
    if (p->pos >= p->str->len) return -1;
    return p->str->chars[p->pos++];
  }
  if (p->kind == PORT_FIN) {
    int c = fgetc(p->fp);
    uint32_t cp;
    int n;
    if (c == EOF) return -1;
    if (c < 0x80) return (int32_t)c;
    if (c >= 0xf0)      { cp = (uint32_t)(c & 7);  n = 3; }
    else if (c >= 0xe0) { cp = (uint32_t)(c & 15); n = 2; }
    else                { cp = (uint32_t)(c & 31); n = 1; }
    while (n-- > 0) {
      int c2 = fgetc(p->fp);
      if (c2 == EOF) break;
      cp = (cp << 6) | (uint32_t)(c2 & 63);
    }
    return (int32_t)cp;
  }
  fprintf(stderr, "scmrt: read from a non-input port\n");
  abort();
  return -1;
}

int32_t port_read_char(obj_t o)
{
  return port_getc(port_of(o));
}

int32_t port_peek_char(obj_t o)
{
  portpay_t *p = port_of(o);
  int32_t c = port_getc(p);
  p->peek = c;
  p->has_peek = 1;
  return c;
}

static void utf8_fputc(FILE *fp, uint32_t c)
{
  if (c < 0x80) {
    fputc((int)c, fp);
  } else if (c < 0x800) {
    fputc((int)(0xc0 | (c >> 6)), fp);
    fputc((int)(0x80 | (c & 63)), fp);
  } else if (c < 0x10000) {
    fputc((int)(0xe0 | (c >> 12)), fp);
    fputc((int)(0x80 | ((c >> 6) & 63)), fp);
    fputc((int)(0x80 | (c & 63)), fp);
  } else {
    fputc((int)(0xf0 | (c >> 18)), fp);
    fputc((int)(0x80 | ((c >> 12) & 63)), fp);
    fputc((int)(0x80 | ((c >> 6) & 63)), fp);
    fputc((int)(0x80 | (c & 63)), fp);
  }
}

void port_write_char(obj_t o, int32_t cp)
{
  portpay_t *p = port_of(o);
  if (p->kind == PORT_SOUT || p->kind == PORT_BOUT) {
    spush_cp(p, cp);
    return;
  }
  if (p->kind == PORT_FOUT) { utf8_fputc(p->fp, (uint32_t)cp); return; }
  fprintf(stderr, "scmrt: write to a non-output port\n");
  abort();
}

static prsink_t port_sink(obj_t o)
{
  portpay_t *p = port_of(o);
  prsink_t sk;
  sk.fp = NULL;
  sk.sp = NULL;
  if (p->kind == PORT_SOUT || p->kind == PORT_BOUT) { sk.sp = p; return sk; }
  if (p->kind == PORT_FOUT) { sk.fp = p->fp; return sk; }
  fprintf(stderr, "scmrt: display/write to a non-output port\n");
  abort();
  return sk;
}

void display_obj_port(obj_t po, obj_t o)
{
  prsink_t sk = port_sink(po);
  pr_sink(&sk, o, 0);
}

void write_obj_port(obj_t po, obj_t o)
{
  prsink_t sk = port_sink(po);
  pr_sink(&sk, o, 1);
}

int32_t file_exists_p(obj_t o)
{
  char *name = str_obj_bytes(o);
  FILE *fp = fopen(name, "r");
  free(name);
  if (fp) { fclose(fp); return 1; }
  return 0;
}

int32_t delete_file_p(obj_t o)
{
  char *name = str_obj_bytes(o);
  int rc = remove(name);
  free(name);
  return rc == 0;
}

void *get_env_payload(obj_t o)
{
  char *name = str_obj_bytes(o);
  const char *v = getenv(name);
  size_t n;
  int32_t *tmp, m;
  strpay_t *r;
  free(name);
  if (!v) return NULL;
  n = strlen(v);
  tmp = (int32_t *)malloc((n + 1) * 4);
  if (!tmp) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  m = utf8_decode(v, n, tmp);
  r = (strpay_t *)malloc(sizeof(strpay_t)
                         + (m > 0 ? (size_t)(m - 1) * 4 : 0));
  if (!r) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
  r->len = m;
  memcpy((char *)(void *)r + 4, tmp, (size_t)m * 4);
  free(tmp);
  return (void *)r;
}

obj_t current_jiffy(void)
{
  return mk_fixnum((int64_t)(clock() * 1000 / CLOCKS_PER_SEC));
}

/* Skint's cursec (i.c): epoch seconds as a flonum, +37.0 for the
   leap-second (TAI) offset Skint applies. */
obj_t current_second(void)
{
  return mk_flonum(difftime(time(NULL), 0) + 37.0);
}

/* The process command line, captured by generated $main before it
   enters compiled code.  The list is built once in the immortal
   static area, so command_line needs neither GC-heap allocation nor
   root juggling and can be called at any point. */
static int32_t rt_argc = 0;
static char **rt_argv = NULL;
static obj_t rt_command_line = SCM_NULL;
static int rt_command_line_ready = 0;

void set_argv(int32_t argc, void *argv)
{
  rt_argc = argc > 0 ? argc : 0;
  rt_argv = (char **)argv;
  rt_command_line = SCM_NULL;
  rt_command_line_ready = 0;
}

obj_t command_line(void)
{
  int32_t i;
  obj_t lst = SCM_NULL;
  ensure_init();
  if (rt_command_line_ready) return rt_command_line;
  for (i = rt_argc - 1; i >= 0; i--) {
    /* the comparisons are explicit because WCPL requires the operands
       of && to have compatible types, and rt_argv is char** while
       rt_argv[i] is char*: "incompatible types of logical operator
       branches".  Written out, both operands are int. [cco] */
    const char *s =
      (rt_argv != NULL && rt_argv[i] != NULL) ? rt_argv[i] : "";
    size_t n = strlen(s);
    int32_t *tmp = (int32_t *)malloc((n + 1) * sizeof(int32_t));
    strpay_t *pay;
    obj_t str;
    obj_t *pair;
    int32_t m;
    if (!tmp) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
    m = utf8_decode(s, n, tmp);
    pay = (strpay_t *)malloc(sizeof(strpay_t)
                             + (m > 0 ? (size_t)(m - 1) * 4 : 0));
    if (!pay) { fprintf(stderr, "scmrt: out of memory\n"); abort(); }
    pay->len = m;
    memcpy((char *)(void *)pay + 4, tmp, (size_t)m * 4);
    free(tmp);
    str = native_obj(&string_cxtype, (void *)pay);
    pair = static_block(SCM_PAIR_HDR, 2);
    pair[0] = str;
    pair[1] = lst;
    lst = (obj_t)(uintptr_t)pair;
  }
  rt_command_line = lst;
  rt_command_line_ready = 1;
  return lst;
}

/* The unique tag object heading a multiple-values vector (element 0;
   the remaining elements are the values).  One immortal instance, so
   identity comparison with eq? is reliable; user code cannot forge
   it because it is never exposed as a value itself. */
static obj_t rt_values_tag = 0;
static int rt_values_tag_ready = 0;

obj_t values_tag(void)
{
  obj_t *cell;
  ensure_init();
  if (rt_values_tag_ready) return rt_values_tag;
  cell = static_block(SCM_HDR(0, MTAG_VECTOR), 0);
  rt_values_tag = (obj_t)(uintptr_t)cell;
  rt_values_tag_ready = 1;
  return rt_values_tag;
}

/* Heap growth copies the static area to a new region at the same
   offsets; every obj_t the runtime caches for itself in a C static
   must follow it, or it keeps pointing into the freed old region.
   (The standard ports are the visible case: flush_port on a stale
   current-output-port after a growth segfaults.) */
static void rebase_runtime_caches(obj_t old_base, size_t old_bytes,
                                  obj_t new_base)
{
  obj_t delta = new_base - old_base;
  /* rt_ports points at the 3-cell block; the CELLS are rebased by the
     static-area scan, this rebases the pointer to the block */
  if (rt_ports && rt_ports - old_base < (obj_t)old_bytes) rt_ports += delta;
  if (rt_command_line - old_base < (obj_t)old_bytes)
    rt_command_line += delta;
  if (rt_values_tag && rt_values_tag - old_base < (obj_t)old_bytes)
    rt_values_tag += delta;
}

/* R7RS: a fixnum is the status, #f is an unsuccessful exit, and anything
   else (including no argument, which the generator passes as #t) is a
   successful one.  Mapping every non-fixnum to 0 made (exit #f) succeed,
   and the default exception handler leaves through (%exit #f) -- so every
   program that died of a Scheme-level error reported it and then exited
   0, which a caller reads as success.  Both hosts give 1 here.  [cco] */
void exit_process(obj_t o)
{
  int code;
  if (is_fixnum(o)) code = (int)fx_val(o);
  else if (o == SCM_FALSE) code = 1;
  else code = 0;
  fflush(NULL);
  exit(code);
}

/* %system runs a shell command.  The WCPL/WASM target has no
   shell: per the project rule the stub prints the command to
   stderr and reports failure (fixnum -1). */
#if defined(__WCPL__)
obj_t system_cmd(obj_t o)
{
  char *cmd = str_obj_bytes(o);
  fprintf(stderr, "scmrt: %%system unavailable on this target: %s\n",
          cmd);
  free(cmd);
  return mk_fixnum(-1);
}
#else
obj_t system_cmd(obj_t o)
{
  char *cmd = str_obj_bytes(o);
  int rc = system(cmd);
  free(cmd);
  return mk_fixnum((int64_t)rc);
}
#endif
